function validate([n]) {
  if (!Number.isInteger(n) || n < 1 || n > 100000) return 'n is a whole number from 1 to 10^5.';
  return null;
}

reference:
function concatenatedBinary(n) {
  const MOD = 1e9 + 7;
  let result = 0;
  let length = 0;
  for (let i = 1; i <= n; i++) {
    if ((i & (i - 1)) === 0) {
      length++;
    }
    result = (result * (1 << length) + i) % MOD;
  }
  return result;
}

brute:
function concatenatedBinary(n) {
  // Read the binary digits of 1..n one at a time, as a person would read the joined string.
  const MOD = 1000000007;
  let value = 0;
  for (let i = 1; i <= n; i++) {
    for (const digit of i.toString(2)) value = (value * 2 + Number(digit)) % MOD;
  }
  return value;
}

